    if (mode === 'settings') iconName = "settings.png";
    if (mode === 'activity') iconName = "activity.png";

    const platformDir = isWin ? "win" : "mac";
    return app.isPackaged
      ? path.join(process.resourcesPath, `assets/fakeicon/${platformDir}/${iconName}`)
